"""COSTS1 one-leg check: is the profit mostly generated by one leg? (rules: research/model/costs1_rules.md section 11, fixed before this code).
Existing data only; no pull; no engine change. The eight headline runs (q 1% / no stop; maker, taker; open10, open20; vault, test months).

DECISION RULES (copied from section 11; the rules file governs)
  LEG GROSS   leg_a = la dir_a (exp(mv_a) - 1), leg_b = lb dir_b (exp(mv_b) - 1); mv = log price(exit stamp) - log price(entry stamp); stamps of section 10.1. ASSERT the legs sum to the saved gross_pnl (1e-4).
              CLOSE version = cleaned closes; MID version = ctxs mid with the G8 table mid as labelled fallback, on trades with all four mids (section 10).
  SPLITS      (a) long (dir +1) vs short (dir -1) legs (beta < 0 pairs have two same-direction legs: all-legs and opposite-direction-only tables, share printed);
              (b) MOVER vs HEDGE, r60 = log close(label t0-1) - log close(label t0-61), closes only; HEADLINE beta-adjusted: mover = leg A if |r60_a| > |beta||r60_b|, leg B if
                  |beta||r60_b| > |r60_a|; RAW beside it: mover = leg with the larger |r60|; missing or tied = unclassified, counted;
              (c) larger vs smaller leg notional (la vs lb; the same split as |beta| < 1 vs > 1), equal legs counted and excluded;
              (d) among trades with saved gross > 0 the share where one leg exceeds 100% of the gross, which leg, share of positive gross; among gross < 0 trades the share where one leg made money;
                  plus the 2 x 2 of leg signs (both up, both down, split) with trade counts and total gross.
              All by period, liquidity tier (costs1 mapping = Part C terciles) and exit reason.
  EXPOSURE    net notional = la dir_a + lb dir_b; BTC return over the trade from BTC.feather 30-minute closes (date = bar OPEN, price(x) = close of the last bar ended at or before x; alternative
              date = bar end printed as one line); slope ($ per +1% BTC) and correlation, mean gross by BTC-return tercile, exposure P&L = sum(net$ x (exp(btc) - 1)) next to gross.
  SIGNS       the close-version sign tests use ga + gb, which equals the saved gross to 1e-4 (asserted).
  COSTS       fees as saved split by leg in proportion to the leg's USD (receipt: leg fees sum to the saved fees); taker runs also the G8 half-spread at the entry and exit stamps (own minute only;
              missing or crossed rows left out and counted). Depth impact, funding and the maker fill model are not split by leg; maker runs show fees only. Leg net is NOT the costed net C.
              Receipt: sum of leg nets vs the saved net A; the gap equals funding plus (taker) the half-spread.
"""
import hashlib
import json
import os
import sys
import time

import numpy as np
import pandas as pd

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import costs_nobounce as N  # noqa: E402

MODEL = N.MODEL
C1, T, TIERS = N.C1, N.T, N.TIERS
RUNS = [(s, mo, fee) for s in ("vault", "test") for mo in (10, 20) for fee in ("maker", "taker")]
OUT = {}
LEGROWS = {}


def log(m):
    print(m, flush=True)


def pct(x):
    return "n/a" if x is None or not np.isfinite(x) else f"{100 * x:.1f}%"


# ------------------------------------------------------------------ BTC
def btc_prices():
    b = pd.read_feather(os.path.join(os.path.dirname(os.path.dirname(MODEL)), "user_data", "normalized", "BTC.feather"))
    d = pd.to_datetime(b["date"], utc=True)
    t = ((d - pd.Timestamp("1970-01-01", tz="UTC")) // pd.Timedelta(minutes=1)).to_numpy().astype("int64")
    order = np.argsort(t)
    return t[order], np.log(b["close"].to_numpy(float)[order])


def btc_at(x, t_bar, lc, open_conv=True):
    ends = t_bar + (30 if open_conv else 0)
    k = np.searchsorted(ends, x, side="right") - 1
    out = np.where(k >= 0, lc[np.clip(k, 0, len(lc) - 1)], np.nan)
    return out


# ------------------------------------------------------------------ one run
def build_run(side, mo, fee, geo, cid, CL, ML, MS, base, Gmid, Gsp, Gcr, bt):
    d = pd.read_parquet(f"{T}trades_q0.01_stopnone_fee{fee}{N.SFX[(side, mo)]}.parquet").reset_index(drop=True)
    hd = pd.read_parquet(f"{C1}costs_headline_conservative_{side}_open{mo}_{fee}.parquet").set_index("event_id").reindex(d["event_id"])
    g = geo.reindex(d["event_id"])
    n = len(d)
    b_ = np.abs(g["beta"].to_numpy())
    la, lb = d["notional"].to_numpy() / (1 + b_), d["notional"].to_numpy() * b_ / (1 + b_)
    z, beta = g["z"].to_numpy(), g["beta"].to_numpy()
    dira = np.where(z >= 0, -1.0, 1.0)
    dirb = np.where(z >= 0, 1.0, -1.0) * np.where(beta >= 0, 1.0, -1.0)
    t0m, exm = N.epoch_min(d["t0"]), N.epoch_min(d["exit_time"])
    ia, ib = d["ticker_a"].map(cid).to_numpy().astype(np.int64), d["ticker_b"].map(cid).to_numpy().astype(np.int64)
    ca0, ca1, cb0, cb1 = CL[ia, t0m - base], CL[ia, exm - base], CL[ib, t0m - base], CL[ib, exm - base]
    ga_c = la * dira * (np.exp(ca1 - ca0) - 1)
    gb_c = lb * dirb * (np.exp(cb1 - cb0) - 1)
    sg = d["gross_pnl"].to_numpy()
    err = np.abs(ga_c + gb_c - sg)
    assert err.max() < 1e-4, f"legs do not sum to the saved gross ({side} open{mo} {fee}): max {err.max()}"
    # mid (ctxs + G8 fallback)
    st4 = [(d["ticker_a"], t0m, ia), (d["ticker_a"], exm, ia), (d["ticker_b"], t0m, ib), (d["ticker_b"], exm, ib)]
    m4 = []
    for c_, s_, i_ in st4:
        mc = ML[i_, s_ - base]
        v = Gmid.reindex(pd.MultiIndex.from_arrays([np.asarray(c_), np.asarray(s_)])).to_numpy(float)
        with np.errstate(invalid="ignore", divide="ignore"):
            gl = np.where(v > 0, np.log(v), np.nan)
        m4.append(np.where(np.isfinite(mc), mc, gl))
    ga_m = la * dira * (np.exp(m4[1] - m4[0]) - 1)
    gb_m = lb * dirb * (np.exp(m4[3] - m4[2]) - 1)
    have_m = np.isfinite(ga_m) & np.isfinite(gb_m)
    # mover / hedge
    r60a = CL[ia, t0m - base] - CL[ia, t0m - 60 - base]
    r60b = CL[ib, t0m - base] - CL[ib, t0m - 60 - base]
    okr = np.isfinite(r60a) & np.isfinite(r60b)
    wa, wb = np.abs(r60a), np.abs(beta) * np.abs(r60b)                    # beta-weighted 60-minute move of each leg on the spread (ln a - beta ln b)
    mov_b = np.where(okr & (wa != wb), np.where(wa > wb, 0, 1), -1)        # HEADLINE: 0 = leg a is the mover, 1 = leg b, -1 unclassified
    mov_r = np.where(okr & (np.abs(r60a) != np.abs(r60b)), np.where(np.abs(r60a) > np.abs(r60b), 0, 1), -1)   # RAW |r60|
    larger = np.where(np.abs(la - lb) < 1e-9, -1, np.where(la > lb, 0, 1))                                                                      # 0 = leg a larger, 1 = leg b larger, -1 equal
    # fees by leg (saved fees split in proportion to the leg's entry and exit USD)
    lax, lbx = la * np.exp(ca1 - ca0), lb * np.exp(cb1 - cb0)
    ef, xf = d["entry_fee"].to_numpy(), d["exit_fee"].to_numpy()
    fee_a = ef * la / (la + lb) + xf * lax / (lax + lbx)
    fee_b = ef * lb / (la + lb) + xf * lbx / (lax + lbx)
    rate = {"maker": 0.00015, "taker": 0.00045}[fee]
    ferr = max(np.abs(ef / (la + lb) / rate - 1).max(), np.abs(xf / (lax + lbx) / rate - 1).max())   # the split is exact only if both fees are the run's rate x USD on every trade
    assert ferr < 1e-9, f"saved fees are not the run's rate x USD on every trade (max relative deviation {ferr:.2e}): the split by leg is not exact"
    # half-spread by leg (taker runs): G8 spread_bp / 2 at the entry and exit stamp, own minute only
    hs = []
    for c_, s_, i_ in st4:
        mi = pd.MultiIndex.from_arrays([np.asarray(c_), np.asarray(s_)])
        sp = Gsp.reindex(mi).to_numpy(float)
        cr = Gcr.reindex(mi).to_numpy(float)
        hs.append(np.where(np.isfinite(sp) & (cr == 0), sp / 2, np.nan))
    hs_a = (la * hs[0] + lax * hs[1]) / 1e4
    hs_b = (lb * hs[2] + lbx * hs[3]) / 1e4
    have_hs = np.isfinite(hs_a) & np.isfinite(hs_b)
    # BTC
    tb, lcb = bt
    out = {}
    for conv in (True, False):
        out[conv] = btc_at(exm, tb, lcb, conv) - btc_at(t0m, tb, lcb, conv)
    rows = pd.DataFrame(dict(
        sgross=sg, tier=hd["tier"].to_numpy(), reason=d["exit_reason"].to_numpy(), notional=d["notional"].to_numpy(), la=la, lb=lb,
        dira=dira, dirb=dirb, ga_c=ga_c, gb_c=gb_c, ga_m=ga_m, gb_m=gb_m, have_m=have_m, mover_b=mov_b, mover_r=mov_r, larger=larger, funding=(d['funding_paid'] - d['funding_received']).to_numpy(), saved_net=d['net'].to_numpy(), hold=d['holding_minutes'].to_numpy(float),
        fee_a=fee_a, fee_b=fee_b, hs_a=hs_a, hs_b=hs_b, have_hs=have_hs, btc=out[True], btc_alt=out[False], month=pd.to_datetime(d["t0"], utc=True).dt.strftime("%Y-%m").to_numpy()))
    rows.attrs['fee_err'] = float(ferr)
    rows.attrs['rate'] = rate
    return rows, float(err.max())


# ------------------------------------------------------------------ tables
def leg_frame(R, version):
    """one row per leg: dir, gross, kind flags, trade gross, set mask"""
    ok = np.ones(len(R), bool) if version == "close" else R["have_m"].to_numpy()
    ga = R["ga_c"] if version == "close" else R["ga_m"]
    gb = R["gb_c"] if version == "close" else R["gb_m"]
    tg = ga + gb if version == "mid" else R["sgross"]
    rows = []
    for leg, (gl, dr, mv, lg) in enumerate(((ga, R["dira"], 0, 0), (gb, R["dirb"], 1, 1))):
        rows.append(pd.DataFrame(dict(
            leg=leg, tr=np.arange(len(R)), ok=ok, gross=gl.to_numpy(), dir=dr.to_numpy(), tgross=np.asarray(tg),
            mover_b=np.where(R["mover_b"].to_numpy() < 0, np.nan, (R["mover_b"].to_numpy() == mv).astype(float)),
            mover_r=np.where(R["mover_r"].to_numpy() < 0, np.nan, (R["mover_r"].to_numpy() == mv).astype(float)),
            larger=np.where(R["larger"].to_numpy() < 0, np.nan, (R["larger"].to_numpy() == lg).astype(float)),
            tier=R["tier"].to_numpy(), reason=R["reason"].to_numpy(), samedir=(R["dira"].to_numpy() == R["dirb"].to_numpy()))))
    return pd.concat(rows, ignore_index=True)


SPLITS = [("long vs short", "is_long", "long", "short"), ("mover vs hedge (beta-adjusted, HEADLINE)", "mover_b", "mover", "hedge"), ("mover vs hedge (raw)", "mover_r", "mover", "hedge"),
          ("larger vs smaller leg", "larger", "larger", "smaller")]


def split_rows(L, key, run, version, groups):
    res = []
    L = L[L["ok"]].copy()
    L["is_long"] = (L["dir"] > 0).astype(float)
    for gname, gm in groups(L):
        sub = L[gm]
        tot = sub.drop_duplicates("tr")["tgross"].sum()
        for nm, col, a_, b_ in SPLITS:
            if col != key:
                continue
            x = sub[sub[col].notna()]
            ya, yb = x[x[col] == 1], x[x[col] == 0]
            res.append(dict(run=run, version=version, group=gname, split=nm, n_trades=int(sub["tr"].nunique()), trade_gross=float(tot),
                            a_name=a_, a_legs=len(ya), a_total=float(ya["gross"].sum()), a_mean=float(ya["gross"].mean()) if len(ya) else None, a_share=float(ya["gross"].sum() / tot) if tot else None,
                            b_name=b_, b_legs=len(yb), b_total=float(yb["gross"].sum()), b_mean=float(yb["gross"].mean()) if len(yb) else None, b_share=float(yb["gross"].sum() / tot) if tot else None,
                            unclassified_legs=int(sub[col].isna().sum())))
    return res


def groups_fn(L):
    yield "ALL", np.ones(len(L), bool)
    for t in TIERS:
        yield t, (L["tier"] == t).to_numpy()
    for r in sorted(set(L["reason"])):
        yield "exit " + str(r), (L["reason"] == r).to_numpy()


def main():
    t00 = time.time()
    log(f"[LEGS] script sha256 {hashlib.sha256(open(__file__, 'rb').read()).hexdigest()[:12]}; rules: costs1_rules.md section 11 (sha256 {hashlib.sha256(open(MODEL + '/costs1_rules.md', 'rb').read()).hexdigest()[:12]})")
    G = pd.read_parquet(C1 + "g8/g8_rows.parquet", columns=["coin", "minute", "mid", "spread_bp", "crossed"]).drop_duplicates(["coin", "minute"]).set_index(["coin", "minute"])
    Gmid, Gsp, Gcr = G["mid"], G["spread_bp"], G["crossed"]
    bt = btc_prices()
    for side in ("vault", "test"):
        ev = N.load_events(side)
        trades_ids = set()
        for mo in (10, 20):
            for fee in ("maker", "taker"):
                trades_ids |= set(pd.read_parquet(f"{T}trades_q0.01_stopnone_fee{fee}{N.SFX[(side, mo)]}.parquet", columns=["event_id"])["event_id"])
        geo = ev[ev["event_id"].isin(trades_ids)].set_index("event_id")
        coins = sorted(set(geo["ticker_a"]) | set(geo["ticker_b"]))
        base = int(geo["t0m"].min()) - 65
        n_min = int(geo["t0m"].max()) + N.K + 2 - base
        cid, CL, ML, MS = N.load_arrays(side, coins, base, n_min)
        for (mo, fee) in [(m, f) for m in (10, 20) for f in ("maker", "taker")]:
            key = f"{side} open{mo} {fee}"
            R, maxerr = build_run(side, mo, fee, geo, cid, CL, ML, MS, base, Gmid, Gsp, Gcr, bt)
            n = len(R)
            tot_g = R["sgross"].sum()
            log(f"[LEGS] ==== {key}: trades {n:,}; legs sum to the saved gross on every trade (max abs diff ${maxerr:.1e}); saved gross ${tot_g:,.2f}; trades with all four mids (ctxs + G8 fallback) {int(R['have_m'].sum()):,} ({pct(R['have_m'].mean())}); same-direction pairs (beta < 0) {int((R['dira'] == R['dirb']).sum()):,} ({pct((R['dira'] == R['dirb']).mean())})")
            assert R["tier"].notna().all(), "a trade has no liquidity tier"
            hm = R["have_m"].to_numpy()
            mon = R["month"].to_numpy()
            log(f"[LEGS]   coverage of trades with all four mids (ctxs + G8 fallback), by entry month: " + "; ".join(f"{mth} {pct(hm[mon == mth].mean())} (n {int((mon == mth).sum()):,})" for mth in sorted(set(mon))) + "; by tier: " + "; ".join(f"{t.split()[0]} {pct(hm[(R['tier'] == t).to_numpy()].mean())} (n {int((R['tier'] == t).sum()):,})" for t in TIERS))
            res = dict(n=n, max_err=maxerr, gross=float(tot_g), n_mid=int(R["have_m"].sum()), share_samedir=float((R["dira"] == R["dirb"]).mean()))
            # mid total vs section 10 gross_mid
            nb = json.load(open(C1 + "costs_nobounce.json"))[side]["reprice"][key]["ctxs + G8 fallback|ALL TIERS"]
            mid_tot = float((R["ga_m"] + R["gb_m"])[R["have_m"]].sum())
            log(f"[LEGS]   mid-version trade total ${mid_tot:,.2f} vs section 10 gross_mid ${nb['gross_mid']:,.2f} (diff {abs(mid_tot - nb['gross_mid']):.2e}); matched trades {int(R['have_m'].sum()):,} vs {nb['n']:,}")
            assert abs(mid_tot - nb["gross_mid"]) < 1e-6 and int(R["have_m"].sum()) == nb["n"], "mid legs do not reproduce the section 10 gross_mid"
            res["cover_month"] = {mth: float(hm[mon == mth].mean()) for mth in sorted(set(mon))}
            res["cover_tier"] = {t: float(hm[(R["tier"] == t).to_numpy()].mean()) for t in TIERS}
            res["fee_rate_dev"] = R.attrs["fee_err"]
            res["mid_check"] = dict(mid_total=mid_tot, section10=nb["gross_mid"])
            res["splits"] = []
            for version in ("close", "mid"):
                L = leg_frame(R, version)
                for nm, col, a_, b_ in SPLITS:
                    rows = split_rows(L, col, key, version, groups_fn)
                    res["splits"] += rows
                    for r in rows:
                        log(f"[LEGS]   [{version:5s}] {nm:21s} {r['group']:20s}: trades {r['n_trades']:>6,}, trade gross ${r['trade_gross']:>9,.2f}; {r['a_name']:7s} legs {r['a_legs']:>6,} total ${r['a_total']:>9,.2f} mean ${(r['a_mean'] if r['a_mean'] is not None else float('nan')):>7.3f} share {pct(r['a_share'])}; {r['b_name']:7s} legs {r['b_legs']:>6,} total ${r['b_total']:>9,.2f} mean ${(r['b_mean'] if r['b_mean'] is not None else float('nan')):>7.3f} share {pct(r['b_share'])}; unclassified legs {r['unclassified_legs']:,}")
            # long/short on opposite-direction trades only
            for version in ("close", "mid"):
                L = leg_frame(R, version)
                L = L[~L["samedir"]]
                rows = split_rows(L, "is_long", key, version, lambda LL: [("ALL (opposite-direction pairs only)", np.ones(len(LL), bool))])
                res["splits"] += rows
                for r in rows:
                    log(f"[LEGS]   [{version:5s}] long vs short, opposite-direction pairs only: trades {r['n_trades']:,}, trade gross ${r['trade_gross']:,.2f}; long ${r['a_total']:,.2f} ({pct(r['a_share'])}), short ${r['b_total']:,.2f} ({pct(r['b_share'])})")
            # (d) one-leg trades, close version and mid version
            res["one_leg"] = {}
            for version in ("close", "mid"):
                ok = np.ones(n, bool) if version == "close" else R["have_m"].to_numpy()
                ga = (R["ga_c"] if version == "close" else R["ga_m"]).to_numpy()
                gb = (R["gb_c"] if version == "close" else R["gb_m"]).to_numpy()
                tg = ga + gb
                for gname, gm in [("ALL", np.ones(n, bool))] + [(t, (R["tier"] == t).to_numpy()) for t in TIERS] + [("exit " + str(r_), (R["reason"] == r_).to_numpy()) for r_ in sorted(set(R["reason"]))]:
                    m = ok & gm
                    pos, neg = m & (tg > 0), m & (tg < 0)
                    one_pos = pos & ((ga > tg) | (gb > tg))
                    one_neg = neg & ((ga > 0) | (gb > 0))
                    which = {}
                    da, db = R["dira"].to_numpy(), R["dirb"].to_numpy()
                    for nm_, cond in (("long leg", ((da > 0) & (ga > tg)) | ((db > 0) & (gb > tg))), ("short leg", ((da < 0) & (ga > tg)) | ((db < 0) & (gb > tg)))):
                        which[nm_] = int((one_pos & cond).sum())
                    which["same-direction pairs among them (long/short counts add up to the total only for opposite-direction pairs)"] = int((one_pos & (da == db)).sum())
                    for mvname, mvcol in (("beta-adj. mover", "mover_b"), ("raw mover", "mover_r")):
                        mvr = R[mvcol].to_numpy()
                        gm_ = np.where(mvr == 0, ga, np.where(mvr == 1, gb, np.nan))
                        gh_ = np.where(mvr == 0, gb, np.where(mvr == 1, ga, np.nan))
                        which[mvname + " leg"] = int((one_pos & (gm_ > tg)).sum())
                        which[mvname.replace("mover", "hedge") + " leg"] = int((one_pos & (gh_ > tg)).sum())
                    lg = R["larger"].to_numpy()
                    gl_ = np.where(lg == 0, ga, np.where(lg == 1, gb, np.nan))
                    gs_ = np.where(lg == 0, gb, np.where(lg == 1, ga, np.nan))
                    which["larger leg"] = int((one_pos & (gl_ > tg)).sum())
                    which["smaller leg"] = int((one_pos & (gs_ > tg)).sum())
                    one_flat = pos & (((ga == tg) & (gb == 0)) | ((gb == tg) & (ga == 0)))
                    r = dict(n_pos=int(pos.sum()), one_leg_pos=int(one_pos.sum()), one_leg_other_flat=int(one_flat.sum()), share_pos=float(one_pos.sum() / pos.sum()) if pos.any() else None,
                             share_of_pos_gross=float(tg[one_pos].sum() / tg[pos].sum()) if pos.any() else None, n_neg=int(neg.sum()), one_leg_neg=int(one_neg.sum()),
                             share_neg=float(one_neg.sum() / neg.sum()) if neg.any() else None, which=which)
                    res["one_leg"][f"{version}|{gname}"] = r
                    log(f"[LEGS]   [{version:5s}] ONE-LEG TRADES {gname:20s}: gross>0 trades {r['n_pos']:,}, one leg > 100% of the gross (the other leg strictly negative) {r['one_leg_pos']:,} ({pct(r['share_pos'])}), one leg with the other flat {r['one_leg_other_flat']:,}, they carry {pct(r['share_of_pos_gross'])} of the positive gross; which leg {which}; gross<0 trades {r['n_neg']:,}, one leg made money {r['one_leg_neg']:,} ({pct(r['share_neg'])})")
            # 2 x 2 of leg signs
            res["signs"] = {}
            for version in ("close", "mid"):
                ok = np.ones(n, bool) if version == "close" else R["have_m"].to_numpy()
                ga = (R["ga_c"] if version == "close" else R["ga_m"]).to_numpy()
                gb = (R["gb_c"] if version == "close" else R["gb_m"]).to_numpy()
                st_a = np.where(ga > 0, "up", np.where(ga < 0, "down", "flat"))
                st_b = np.where(gb > 0, "up", np.where(gb < 0, "down", "flat"))
                cells = {}
                for x_, y_ in (("up", "up"), ("down", "down"), ("flat", "flat"), ("up", "down"), ("up", "flat"), ("down", "flat")):
                    cells[f"{x_} + {y_}"] = ok & (((st_a == x_) & (st_b == y_)) | ((st_a == y_) & (st_b == x_)))
                res["signs"][version] = {k: dict(n=int(v.sum()), gross=float((ga + gb)[v].sum())) for k, v in cells.items()}
                log(f"[LEGS]   [{version:5s}] LEG SIGNS: " + "; ".join(f"{k} {v['n']:,} trades, total gross ${v['gross']:,.2f}" for k, v in res["signs"][version].items())  + "  (up = leg gross > 0, down = < 0, flat = exactly 0)")
            # exposure
            net = R["la"] * R["dira"] + R["lb"] * R["dirb"]
            share = (net / R["notional"]).to_numpy()
            qs = np.percentile(share, [1, 5, 25, 50, 75, 95, 99])
            log(f"[LEGS]   EXPOSURE net notional (long minus short): mean ${net.mean():,.2f} ({pct(share.mean())} of N), mean |net share| {pct(np.abs(share).mean())}; quantiles of net share 1/5/25/50/75/95/99: " + " ".join(f"{x:+.3f}" for x in qs))
            ex = dict(net_mean=float(net.mean()), share_mean=float(share.mean()), abs_share_mean=float(np.abs(share).mean()), q=qs.tolist())
            for lab, col in (("date = bar open (primary)", "btc"), ("date = bar end (alternative)", "btc_alt")):
                bt_r = R[col].to_numpy()
                ok = np.isfinite(bt_r)
                gro = R["sgross"].to_numpy()
                sl = np.polyfit(bt_r[ok] * 100, gro[ok], 1)[0]
                cr = np.corrcoef(bt_r[ok], gro[ok])[0, 1]
                gbp = gro / R["notional"].to_numpy() * 1e4
                sl_bp = np.polyfit(bt_r[ok] * 100, gbp[ok], 1)[0]
                cr_bp = np.corrcoef(bt_r[ok], gbp[ok])[0, 1]
                expo = float((net.to_numpy()[ok] * (np.exp(bt_r[ok]) - 1)).sum())
                ter = pd.qcut(pd.Series(bt_r[ok]).rank(method="first"), 3, labels=["BTC down third", "BTC middle third", "BTC up third"])
                dfm = pd.DataFrame(dict(g=gro[ok], hold=R["hold"].to_numpy()[ok], mu=(R["reason"].to_numpy()[ok] == "mu").astype(float)))
                tm = dfm.groupby(ter.to_numpy()).agg(size=("g", "size"), mean=("g", "mean"), sum=("g", "sum"), hold=("hold", "mean"), mu=("mu", "mean"))
                log(f"[LEGS]   BTC [{lab}]: trades with a BTC return {int(ok.sum()):,}; slope of trade gross on BTC return ${sl:,.3f} per +1% BTC, correlation {cr:+.4f}; gross as bp of notional: slope {sl_bp:+.3f} bp per +1%, correlation {cr_bp:+.4f}; exposure P&L (net$ x BTC return, beta 1 assumed) ${expo:,.2f} vs gross ${gro[ok].sum():,.2f}; mean gross by BTC tercile: " + "; ".join(f"{k} ${r['mean']:.3f} (n {int(r['size']):,}, total ${r['sum']:,.2f}, mean holding {r['hold']:.0f} min, mu exits {r['mu']:.1%})" for k, r in tm.iterrows()))
                ex[col] = dict(n=int(ok.sum()), slope=float(sl), corr=float(cr), slope_bp=float(sl_bp), corr_bp=float(cr_bp), exposure_pnl=expo, gross=float(gro[ok].sum()), terciles={k: dict(n=int(r["size"]), mean=float(r["mean"]), total=float(r["sum"]), hold=float(r["hold"]), mu_share=float(r["mu"])) for k, r in tm.iterrows()})
            res["exposure"] = ex
            # costs per leg
            res["costs"] = {}
            taker = fee == "taker"
            ok_c = R["have_hs"].to_numpy() if taker else np.ones(n, bool)
            log(f"[LEGS]   COSTS PER LEG ({'fees + G8 half-spread' if taker else 'fees only; the maker fill model is not split by leg'}): LEG NET IS NOT THE COSTED NET C: no depth impact, no funding, no fill model; this answers which leg makes the profit only. Trades in the table {int(ok_c.sum()):,} of {n:,} (left out for a missing or crossed G8 row: {int((~ok_c).sum()):,}); saved entry and exit fee = the run's rate ({R.attrs['rate']:.5f}) x USD on every trade (max relative deviation {R.attrs['fee_err']:.1e}), so the split by leg dollars is exact")
            legnet = (R["ga_c"] + R["gb_c"] - R["fee_a"] - R["fee_b"] - (R["hs_a"] + R["hs_b"] if taker else 0.0)).to_numpy()
            sA, sL, sFd = R["saved_net"].to_numpy()[ok_c].sum(), legnet[ok_c].sum(), R["funding"].to_numpy()[ok_c].sum()
            sH = (R["hs_a"] + R["hs_b"]).to_numpy()[ok_c].sum() if taker else 0.0
            assert abs((sL - sA) - (sFd - sH)) < 1e-6, "leg nets vs saved net: the gap is not funding minus half-spread"
            log(f"[LEGS]   RECEIPT sum of leg nets ${sL:,.2f} vs saved net A ${sA:,.2f} on the same {int(ok_c.sum()):,} trades; gap ${sL - sA:,.2f} = funding paid net added back (${sFd:,.2f})" + (f" less the half-spread (${sH:,.2f})" if taker else "") + f" = ${sFd - sH:,.2f} (asserted equal to 1e-6)")
            res["receipt_legnet"] = dict(n=int(ok_c.sum()), n_all=int(n), leg_net=float(sL), saved_net=float(sA), funding=float(sFd), half_spread=float(sH))
            for gname, gm in [("ALL", np.ones(n, bool))] + [(t, (R["tier"] == t).to_numpy()) for t in TIERS]:
                m = ok_c & gm
                if not m.any():
                    continue
                for nm, first_is_a, classified, a_n, b_n in (
                        ("long vs short", R["dira"].to_numpy() > 0, R["dira"].to_numpy() != R["dirb"].to_numpy(), "long", "short"),
                        ("mover vs hedge (beta-adjusted, HEADLINE)", R["mover_b"].to_numpy() == 0, R["mover_b"].to_numpy() >= 0, "mover", "hedge"),
                        ("mover vs hedge (raw)", R["mover_r"].to_numpy() == 0, R["mover_r"].to_numpy() >= 0, "mover", "hedge"),
                        ("larger vs smaller leg", R["larger"].to_numpy() == 0, R["larger"].to_numpy() >= 0, "larger", "smaller")):
                    # first_is_a: the FIRST named group (long / mover / larger) is leg A of the trade; classified: the trade has a classification for this split
                    valid = m & classified
                    cells = {}
                    for which_, sel_a, sel_b in ((a_n, valid & first_is_a, valid & ~first_is_a), (b_n, valid & ~first_is_a, valid & first_is_a)):
                        g_ = R["ga_c"].to_numpy()[sel_a].sum() + R["gb_c"].to_numpy()[sel_b].sum()
                        f_ = R["fee_a"].to_numpy()[sel_a].sum() + R["fee_b"].to_numpy()[sel_b].sum()
                        h_ = (R["hs_a"].to_numpy()[sel_a].sum() + R["hs_b"].to_numpy()[sel_b].sum()) if taker else 0.0
                        cells[which_] = dict(legs=int(sel_a.sum() + sel_b.sum()), gross=float(g_), fees=float(f_), half_spread=float(h_), net=float(g_ - f_ - h_))
                    excluded = int((m & ~classified).sum())
                    res["costs"][f"{gname}|{nm}"] = dict(cells=cells, excluded_trades=excluded, trades=int(m.sum()))
                    log(f"[LEGS]     {gname:20s} {nm:41s}: " + "; ".join(f"{k} legs {v['legs']:,} gross ${v['gross']:,.2f} fees ${v['fees']:,.2f}" + (f" half-spread ${v['half_spread']:,.2f}" if taker else "") + f" net ${v['net']:,.2f}" for k, v in cells.items()) + f"; trades in the table {int(m.sum()):,}, left out of this split (same-direction pair / unclassified / equal legs) {excluded:,}")
            OUT[key] = res
        del CL, ML, MS
    json.dump(OUT, open(C1 + "costs_legs.json", "w"), indent=1, default=float)
    log(f"[LEGS] wrote logs/costs1/costs_legs.json; total {time.time() - t00:.0f}s")


if __name__ == "__main__":
    main()
